  import React from 'react'
  import { MDXTag } from '@mdx-js/tag'
  import { Playground, PropsTable } from 'docz'
import { Header, Paragraph, Text, Small } from '../src'

const layoutProps = {

};
export default class MDXContent extends React.Component {
  constructor(props) {
    super(props)
    this.layout = null
  }
  render() {
    const { components, ...props } = this.props

    return <MDXTag
             name="wrapper"

             components={components}>
<MDXTag name="h1" components={components} props={{"id":"text"}}>{`Text`}</MDXTag>
<MDXTag name="h2" components={components} props={{"id":"basic-usage"}}>{`Basic usage`}</MDXTag>
<MDXTag name="p" components={components}>{`All typography elements support the `}<MDXTag name="inlineCode" components={components} parentName="p">{`<Box>`}</MDXTag>{` spacing properties:`}</MDXTag>
<MDXTag name="pre" components={components}><MDXTag name="code" components={components} parentName="pre" props={{"className":"language-js"}}>{`  <Header pt={10}>Hello, World!</Header>
`}</MDXTag></MDXTag>
<Playground __codesandbox={`undefined`} __position={0} __code={'<Header>Hello, World!\n</Playground>'} __scope={{props: this ? this.props : props,Header,Paragraph,Text,Small}}>
  <Header>Hello, World!</Header>
</Playground>
<MDXTag name="h2" components={components} props={{"id":""}}></MDXTag>
           </MDXTag>
  }
}
